/bin/bash -lc "cat > /workspace/pixel-editor/index.html << 'EOF'
<"'!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Pixel Painter</title>
<style>
  :root {
    --bg: #1e1e2e;
    --panel: #27273a;
    --accent: #89b4fa;
    --accent-2: #f5c2e7;
    --text: #cdd6f4;
    --muted: #6c7086;
    --danger: #f38ba8;
  }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    min-height: 100vh;
    font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
    background: var(--bg);
    color: var(--text);
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 24px 16px;
  }
  h1 {
    font-size: 22px;
    letter-spacing: 1px;
    margin: 0 0 16px;
    font-weight: 700;
  }
  h1 span { color: var(--accent); }
  .app {
    display: flex;
    gap: 20px;
    flex-wrap: wrap;
    justify-content: center;
    align-items: flex-start;
  }
  .panel {
    background: var(--panel);
    border-radius: 14px;
    padding: 16px;
    box-shadow: 0 8px 30px rgba(0,0,0,.3);
  }
  .canvas-wrap {
    position: relative;
    line-height: 0;
    border-radius: 8px;
    overflow: hidden;
    background: repeating-conic-gradient(#2a2a3c 0% 25%, #333350 0% 50%) 0 0 / 16px 16px;
  }
  canvas#art {
    display: block;
    cursor: crosshair;
    image-rendering: pixelated;
    touch-action: none;
  }
  .gridlines canvas { position: absolute; inset: 0; pointer-events: none; }
  .tools {
    display: flex;
    flex-direction: column;
    gap: 14px;
    min-width: 180px;
    max-width: 220px;
  }
  .tools h2 {
    font-size: 13px;
    text-transform: uppercase;
    letter-spacing: 1px;
    color: var(--muted);
    margin: 4px 0 6px;
  }
  .icon-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 8px;
  }
  .tool-btn {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 4px;
    padding: 8px 4px;
    background: #2f2f4a;
    border: 2px solid transparent;
    border-radius: 10px;
    color: var(--text);
    cursor: pointer;
    font-size: 11px;
    transition: border-color .15s, background .15s, transform .05s;
  }
  .tool-btn:hover { background: #3a3a5a; }
  .tool-btn.active { border-color: var(--accent); background: #3a3a5a; }
  .tool-btn:active { transform: scale(.96); }
  .tool-btn svg { width: 22px; height: 22px; }
  .row { display: flex; align-items: center; gap: 10px; }
  .row label { font-size: 12px; color: var(--muted); }
  .swatches {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 6px;
  }
  .swatch {
    aspect-ratio: 1;
    border-radius: 7px;
    cursor: pointer;
    border: 2px solid transparent;
    transition: transform .1s, border-color .1s;
  }
  .swatch:hover { transform: scale(1.12); }
  .swatch.active { border-color: #fff; }
  input[type="range"] { width: 100%; accent-color: var(--accent); }
  input[type="color"] {
    width: 100%;
    height: 34px;
    border: none;
    border-radius: 8px;
    background: none;
    cursor: pointer;
    padding: 0;
  }
  input[type="color"]::-webkit-color-swatch-wrapper { padding: 0; }
  input[type="color"]::-webkit-color-swatch { border: none; border-radius: 8px; }
  .btn {
    width: 100%;
    padding: 9px;
    border: none;
    border-radius: 9px;
    background: var(--accent);
    color: #1e1e2e;
    font-weight: 700;
    cursor: pointer;
    font-size: 13px;
    transition: filter .15s, transform .05s;
  }
  .btn:hover { filter: brightness(1.1); }
  .btn:active { transform: scale(.97); }
  .btn.ghost { background: #2f2f4a; color: var(--text); }
  .btn.danger { background: var(--danger); color: #1e1e2e; }
  .hint {
    font-size: 11px;
    color: var(--muted);
    text-align: center;
    margin-top: 8px;
  }
  footer { margin-top: 20px; font-size: 12px; color: var(--muted); }
</style>
</head>
<body>
  <h1>PIXEL <span>PAINTER</span></h1>

  <div class="app">
    <div class="canvas-wrap panel" id="wrap">
      <canvas id="art" width="320" height="320"></canvas>
      <div class="gridlines"><canvas id="grid" width="320" height="320"></canvas></div>
    </div>

    <div class="tools panel">
      <div>
        <h2>Tools</h2>
        <div class="icon-grid" id="toolbar"></div>
      </div>

      <div>
        <h2>Colors</h2>
        <div class="swatches" id="swatches"></div>
        <div class="row" style="margin-top:10px;align-items:center;">
          <span style="font-size:13px;">Custom</span>
          <input type="color" id="custom" value="#89b4fa">
        </div>
      </div>

      <div>
        <h2>Canvas</h2>
        <div class="row">
          <label for="size">Size</label>
          <input type="range" id="size" min="8" max="64" value="16" step="2">
          <span id="sizeVal" style="font-size:12px;">16</span>
        </div>
        <div class="row" style="margin-top:6px;">
          <label for="zoom">Zoom</label>
          <input type="range" id="zoom" min="2" max="24" value="10">
          <span id="zoomVal" style="font-size:12px;">10</span>
        </div>
        <div class="row" style="margin-top:8px;justify-content:space-between;">
          <label for="symmetric" style="margin:0;">Mirror</label>
          <input type="checkbox" id="symmetric" style="accent-color:var(--accent);">
        </div>
      </div>

      <div style="display:flex;flex-direction:column;gap:8px;">
        <button class="btn" id="undo">Undo</button>
        <button class="btn" id="redo">Redo</button>
        <button class="btn ghost" id="clear">Clear</button>
        <button class="btn ghost" id="export">Export PNG</button>
      </div>

      <div>
        <h2>Eraser · Bucket · Symmetry</h2>
        <div class="icon-grid">
          <button class="btn ghost" id="fill">Fill</button>
          <button class="btn ghost" id="eyedrop">Pick</button>
        </div>
        <p class="hint">Click a pixel to draw · Right-click to erase</p>
      </div>
    </div>
  </div>

  <footer>Made with zero dependencies · runs entirely in your browser</footer>

<script>
(() => {
  const art = document.getElementById('"'art');
  const gridCanvas = document.getElementById('grid');
  const gctx = gridCanvas.getContext('2d');
  const ctx = art.getContext('2d', { willReadFrequently: true });

  let size = 16;
  let zoom = 10;
  let currentColor = '#89b4fa';
  let tool = 'pen';
  let mirror = false;

  const state = { pixels: null, undoStack: [], redoStack: [] };

  const PREVIEW = 320; // base logical canvas size

  const PRESET_COLORS = [
    '#1e1e2e', '#89b4fa', '#a6e3a1', '#f5c2e7',
    '#f9e2af', '#f38ba8', '#eba0ac', '#94e2d5',
    '#ffffff', '#585b70', '#fab387', '#f38ba8'
  ];

  const svg = {
    pen: '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M12 19l7-7 3 3-7 7-3-3z\"/><path d=\"M18 13l-1.5-7.5L2 2l3.5 14.5L13 18z\"/><path d=\"M2 2l7.586 7.586\"/><circle cx=\"11\" cy=\"11\" r=\"2\"/></svg>',
    eraser: '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M19 20H9\"/><path d=\"M18 4l4 4L11 20l-4-4L18 4z\"/></svg>',
    bucket: '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M10 2v2\"/><path d=\"M14 2v2\"/><path d=\"M12 2v7\"/><path d=\"M3 9l9 -7 9 7v2a5 5 0 0 1 -5 5h-8a5 5 0 0 1 -5 -5z\"/><path d=\"M8 21h8\"/></svg>',
    eyedrop: '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M2 22l5-15 3 3 9-9 2 2-9 9 1 1 2-2 2 2-4 5-6-1z\"/></svg>'
  };

  init();

  function init() {
    size = 16; zoom = 10;
    state.pixels = freshGrid(size);
    state.undoStack = [];
    state.redoStack = [];
    buildToolbar();
    buildSwatches();
    bindEvents();
    render();
    applyZoom();
  }

  function freshGrid(n) {
    return Array.from({ length: n }, () => Array(n).fill('#00000000'));
  }

  function buildToolbar() {
    const tb = document.getElementById('toolbar');
    const tools = [
      { id: 'pen', name: 'Pen', svg: svg.pen },
      { id: 'eraser', name: 'Eraser', svg: svg.eraser },
      { id: 'bucket', name: 'Fill', svg: svg.bucket },
      { id: 'eyedrop', name: 'Pick', svg: svg.eyedrop }
    ];
    tb.innerHTML = '';
    tools.forEach(t => {
      const b = document.createElement('button');
      b.className = 'tool-btn' + (t.id === tool ? ' active' : '');
      b.dataset.tool = t.id;
      b.innerHTML = t.svg + '<span>' + t.name + '</span>';
      b.addEventListener('click', () => setTool(t.id));
      tb.appendChild(b);
    });
  }

  function setTool(t) {
    tool = t;
    document.querySelectorAll('.tool-btn').forEach(b =>
      b.classList.toggle('active', b.dataset.tool === t));
  }

  function buildSwatches() {
    const sw = document.getElementById('swatches');
    sw.innerHTML = '';
    PRESET_COLORS.forEach(c => {
      const d = document.createElement('div');
      d.className = 'swatch' + (c === currentColor ? ' active' : '');
      d.style.background = c;
      d.addEventListener('click', () => {
        currentColor = c;
        document.getElementById('custom').value = c;
        document.querySelectorAll('.swatch').forEach(s => s.classList.remove('active'));
        d.classList.add('active');
      });
      sw.appendChild(d);
    });
  }

  function bindEvents() {
    document.getElementById('custom').addEventListener('input', e => {
      currentColor = e.target.value;
    });

    const sizeEl = document.getElementById('size');
    sizeEl.addEventListener('input', e => {
      const n = parseInt(e.target.value, 10);
      resize(n);
    });

    const zoomEl = document.getElementById('zoom');
    zoomEl.addEventListener('input', e => {
      zoom = parseInt(e.target.value, 10);
      document.getElementById('zoomVal').textContent = zoom;
      applyZoom();
    });

    document.getElementById('symmetric').addEventListener('change', e => {
      mirror = e.target.checked;
    });

    document.getElementById('undo').addEventListener('click', undo);
    document.getElementById('redo').addEventListener('click', redo);
    document.getElementById('clear').addEventListener('click', () => push(); clearPixels());
    document.getElementById('export').addEventListener('click', exportPNG);
    document.getElementById('fill').addEventListener('click', () => setTool('bucket'));
    document.getElementById('eyedrop').addEventListener('click', () => setTool('eyedrop'));

    // Drawing on the art canvas
    let drawing = false;
    art.addEventListener('pointerdown', e => {
      e.preventDefault();
      art.setPointerCapture(e.pointerId);
      drawing = true;
      const pt = eventToPixel(e);
      if (pt) {
        push();
        applyPaint(pt.x, pt.y, e);
      }
    });
    art.addEventListener('pointermove', e => {
      if ("'!drawing) return;
      const pt = eventToPixel(e);
      if (pt) applyPaint(pt.x, pt.y, e);
    });
    const endDraw = () => { drawing = false; };
    art.addEventListener('"'pointerup', endDraw);
    art.addEventListener('pointerleave', endDraw);

    // Right click erases
    art.addEventListener('contextmenu', e => e.preventDefault());
  }

  function eventToPixel(e) {
    const rect = art.getBoundingClientRect();
    const x = Math.floor((e.clientX - rect.left) / rect.width * size);
    const y = Math.floor((e.clientY - rect.top) / rect.height * size);
    if (x < 0 || y < 0 || x >= size || y >= size) return null;
    return { x, y };
  }

  function applyPaint(x, y, e) {
    if (tool === 'eyedrop') {
      const c = state.pixels[y][x];
      if (c && c "'!== '"'#00000000') {
        currentColor = c;
        document.getElementById('custom').value = c;
        updateSwatchActive();
      }
      return;
    }
    if (tool === 'bucket') {
      floodFill(x, y, currentColor);
      finalize();
      return;
    }
    if (tool === 'eraser') {
      paintOne(x, y, '#00000000');
    } else {
      paintOne(x, y, currentColor);
    }
    if (mirror) {
      paintOne(size - 1 - x, y, '#00000000'.slice(0, 0) + (tool === 'eraser' ? '#00000000' : currentColor));
    }
    finalize();
  }

  function paintOne(x, y, color) {
    if (x < 0 || y < 0 || x >= size || y >= size) return;
    state.pixels[y][x] = color;
  }

  function floodFill(sx, sy, color) {
    const target = state.pixels[sy][sx];
    if (target === color) return;
    const stack = [[sx, sy]];
    const visited = new Set();
    while (stack.length) {
      const [x, y] = stack.pop();
      const k = y * size + x;
      if (visited.has(k)) continue;
      visited.add(k);
      if (state.pixels[y][x] "'!== target) continue;
      state.pixels[y][x] = color;
      if (x > 0) stack.push([x - 1, y]);
      if (x < size - 1) stack.push([x + 1, y]);
      if (y > 0) stack.push([x, y - 1]);
      if (y < size - 1) stack.push([x, y + 1]);
    }
  }

  function updateSwatchActive() {
    document.querySelectorAll('"'.swatch').forEach((s, i) => {
      s.classList.toggle('active', PRESET_COLORS[i] === currentColor);
    });
  }

  function resize(n) {
    const next = freshGrid(n);
    const copy = Math.min(n, size);
    for (let y = 0; y < copy; y++)
      for (let x = 0; x < copy; x++)
        next[y][x] = state.pixels[y][x];
    push();
    size = n;
    state.pixels = next;
    document.getElementById('sizeVal').textContent = n;
    render();
  }

  function push() {
    state.undoStack.push(state.pixels.map(r => r.slice()));
    if (state.undoStack.length > 200) state.undoStack.shift();
    state.redoStack = [];
  }

  function undo() {
    if ("'!state.undoStack.length) return;
    state.redoStack.push(state.pixels.map(r => r.slice()));
    state.pixels = state.undoStack.pop();
    finalize();
  }

  function redo() {
    if (!state.redoStack.length) return;
    state.undoStack.push(state.pixels.map(r => r.slice()));
    state.pixels = state.redoStack.pop();
    finalize();
  }

  function clearPixels() {
    state.pixels = freshGrid(size);
    finalize();
  }

  function finalize() { render(); }

  function render() {
    ctx.clearRect(0, 0, PREVIEW, PREVIEW);
    const cell = PREVIEW / size;
    for (let y = 0; y < size; y++) {
      for (let x = 0; x < size; x++) {
        const c = state.pixels[y][x];
        if (!c || c === '"'#00000000') continue;
        ctx.fillStyle = c;
        ctx.fillRect(x * cell, y * cell, cell + 0.5, cell + 0.5);
      }
    }
    drawGrid();
  }

  function drawGrid() {
    gctx.clearRect(0, 0, PREVIEW, PREVIEW);
    gctx.strokeStyle = 'rgba(205,214,244,0.12)';
    gctx.lineWidth = 1;
    const cell = PREVIEW / size;
    gctx.beginPath();
    for (let i = 1; i < size; i++) {
      gctx.moveTo(i * cell, 0);
      gctx.lineTo(i * cell, PREVIEW);
      gctx.moveTo(0, i * cell);
      gctx.lineTo(PREVIEW, i * cell);
    }
    gctx.stroke();
  }

  function applyZoom() {
    art.width = size * zoom;
    art.height = size * zoom;
    gridCanvas.width = size * zoom;
    gridCanvas.height = size * zoom;
    art.style.width = size * zoom + 'px';
    art.style.height = size * zoom + 'px';
    gridCanvas.style.width = size * zoom + 'px';
    gridCanvas.style.height = size * zoom + 'px';
    // re-render at new resolution
    redrawAtZoom();
  }

  let logicalScale = 1;
  function redrawAtZoom() {
    logicalScale = (size * zoom) / PREVIEW;
    render();
  }

  // Override render to work at physical zoom resolution
  const baseRender = render;
  render = function() {
    ctx.clearRect(0, 0, art.width, art.height);
    const cell = art.width / size;
    for (let y = 0; y < size; y++) {
      for (let x = 0; x < size; x++) {
        const c = state.pixels[y][x];
        if ("'!c || c === '"'#00000000') continue;
        ctx.fillStyle = c;
        ctx.fillRect(x * cell, y * cell, cell + 0.5, cell + 0.5);
      }
    }
    gctx.clearRect(0, 0, gridCanvas.width, gridCanvas.height);
    gctx.strokeStyle = 'rgba(205,214,244,0.12)';
    gctx.lineWidth = 1;
    const cellG = gridCanvas.width / size;
    gctx.beginPath();
    for (let i = 1; i < size; i++) {
      gctx.moveTo(i * cellG, 0);
      gctx.lineTo(i * cellG, gridCanvas.height);
      gctx.moveTo(0, i * cellG);
      gctx.lineTo(gridCanvas.width, i * cellG);
    }
    gctx.stroke();
  };

  function exportPNG() {
    const scale = 1; // 1 px per canvas pixel
    gctx.clearRect(0, 0, gridCanvas.width, gridCanvas.height);
    const link = document.createElement('a');
    const out = document.createElement('canvas');
    out.width = size * zoom;
    out.height = size * zoom;
    const octx = out.getContext('2d');
    const cell = out.width / size;
    for (let y = 0; y < size; y++)
      for (let x = 0; x < size; x++) {
        const c = state.pixels[y][x];
        if (c && c "'!== '"'#00000000') { octx.fillStyle = c; octx.fillRect(x * cell, y * cell, cell, cell); }
      }
    link.download = 'pixel-art.png';
    link.href = out.toDataURL('image/png');
    link.click();
    render(); // restore grid
  }

  // Initial render at zoom
  applyZoom();
})();
</script>
</body>
</html>
EOF
echo \"written\""

